(function(){
"use strict";
// Generated in the user's code style; assembled by Lab.tsScript in ts-core.js.
Lab.ts({
"vec-new":{"k":"S","what":"A marker placed by a Vector3, with a line from the origin and its X, Y, Z and Magnitude shown above it.","services":[],"variables":"","functions":"","setup":"local vector = Vector3.new(6, 4, -3)\nMakePart(Vector3.new(0.8, 0.8, 0.8), ORIGIN, Color3.new(1, 1, 1)) -- the origin\nlocal marker = MakePart(Vector3.new(1.5, 1.5, 1.5), ORIGIN + vector, Color3.fromRGB(226, 133, 26))\nDrawLine(MakeLinePart(), ORIGIN, ORIGIN + vector)\n\nMakeLabel(\n\tmarker,\n\tstring.format(\"v = (%g, %g, %g)   Magnitude %.2f\", vector.X, vector.Y, vector.Z, vector.Magnitude)\n)\n\nprint(vector.X, vector.Y, vector.Z, vector.Magnitude)","runtime":""},
"vec-sub":{"k":"S","what":"Point B circles around point A. The beam is B − A, labelled with its length (the distance).","services":[],"variables":"","functions":"","setup":"local A = ORIGIN + Vector3.new(0, 2, 0)\nlocal partA = MakePart(Vector3.new(1.5, 1.5, 1.5), A, Color3.fromRGB(18, 147, 154))\nlocal partB = MakePart(Vector3.new(1.5, 1.5, 1.5), A, Color3.fromRGB(194, 65, 142))\nlocal beam = MakeLinePart()\nlocal label = MakeLabel(partA)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tpartB.Position = A + Vector3.new(math.cos(now) * 10, 3 + math.sin(now * 2) * 2, math.sin(now) * 10)\n\tlocal offset = partB.Position - partA.Position -- the arrow from A to B\n\tDrawLine(beam, partA.Position, partA.Position + offset)\n\tlabel.Text = string.format(\n\t\t\"B - A = (%.1f, %.1f, %.1f)   distance %.1f\",\n\t\toffset.X,\n\t\toffset.Y,\n\t\toffset.Z,\n\t\toffset.Magnitude\n\t)\nend)"},
"vec-scale":{"k":"S","what":"An arrow is scaled by a number that swings from −1.5 to 2 (negative flips it), plus its flattened shadow (Y removed).","services":[],"variables":"","functions":"","setup":"local vector = Vector3.new(6, 4, -2)\nlocal base = ORIGIN + Vector3.new(0, 0.5, 0)\nlocal arrow, shadow = MakeLinePart(), MakeLinePart(Color3.fromRGB(194, 65, 142))\nlocal tip = MakePart(Vector3.new(1, 1, 1), base, Color3.fromRGB(226, 133, 26))\nlocal label = MakeLabel(tip)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal scale = 0.25 + 1.75 * math.sin(os.clock()) -- from -1.5 to 2\n\tlocal scaled = vector * scale\n\tDrawLine(arrow, base, base + scaled)\n\tDrawLine(shadow, base, base + scaled * Vector3.new(1, 0, 1)) -- flatten: keep X and Z\n\ttip.Position = base + scaled\n\tlabel.Text = string.format(\"v * %.2f   length %.1f\", scale, scaled.Magnitude)\nend)"},
"vec-mag":{"k":"S","what":"A tower with a 20-stud range. It turns red and shows the distance when a player is inside the range.","services":[],"variables":"local _range = 20","functions":"","setup":"local tower = MakePart(Vector3.new(3, 8, 3), ORIGIN + Vector3.new(0, 4, 0), Color3.fromRGB(90, 160, 230))\n\nlocal ring = MakePart(\n\tVector3.new(0.2, _range * 2, _range * 2),\n\tORIGIN + Vector3.new(0, 0.1, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{\n\t\tShape = Enum.PartType.Cylinder,\n\t\tTransparency = 0.8,\n\t\tCanCollide = false,\n\t\tOrientation = Vector3.new(0, 0, 90),\n\t}\n)\n\nlocal label = MakeLabel(tower)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(tower.Position)\n\tif not root then\n\t\tlabel.Text = \"no players\"\n\t\treturn\n\tend\n\tlocal distance = ((root.Position - tower.Position) * Vector3.new(1, 0, 1)).Magnitude -- ignore height\n\tlocal inRange = distance <= _range\n\ttower.Color = inRange and Color3.fromRGB(230, 60, 60) or Color3.fromRGB(90, 160, 230)\n\tlabel.Text = string.format(\"%.1f studs  %s\", distance, inRange and \"IN RANGE\" or \"\")\nend)"},
"vec-unit":{"k":"S","what":"A turret fires a ball at the nearest player once a second. The velocity is direction.Unit × speed, so every shot flies at the same speed.","services":[],"variables":"local _speed = 40","functions":"","setup":"local gun = MakePart(Vector3.new(2, 2, 2), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(60, 60, 70))","runtime":"while true do\n\tlocal root = GetNearestRoot(gun.Position, 80)\n\tif root then\n\t\tlocal direction = (root.Position - gun.Position).Unit -- length 1: direction only\n\t\tlocal velocity = direction * _speed\n\t\tlocal ball = MakePart(\n\t\t\tVector3.new(0.8, 0.8, 0.8),\n\t\t\tgun.Position,\n\t\t\tColor3.fromRGB(226, 133, 26),\n\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n\t\t)\n\t\ttask.spawn(function()\n\t\t\tlocal start = os.clock()\n\t\t\twhile os.clock() - start < 2 do\n\t\t\t\tball.Position += velocity * runService.Heartbeat:Wait()\n\t\t\tend\n\t\t\tball:Destroy()\n\t\tend)\n\tend\n\ttask.wait(1)\nend"},
"vec-lerp":{"k":"S","what":"A marker slides between two posts with A:Lerp(B, alpha), alpha going 0 → 1 → 0.","services":[],"variables":"","functions":"","setup":"local A, B = ORIGIN + Vector3.new(-10, 2, 0), ORIGIN + Vector3.new(10, 6, -4)\nMakePart(Vector3.new(1, 4, 1), A - Vector3.new(0, 1.5, 0), Color3.fromRGB(18, 147, 154))\nMakePart(Vector3.new(1, 4, 1), B - Vector3.new(0, 1.5, 0), Color3.fromRGB(194, 65, 142))\n\nlocal marker =\n\tMakePart(Vector3.new(1.5, 1.5, 1.5), A, Color3.fromRGB(226, 133, 26), { Shape = Enum.PartType.Ball })\n\nlocal label = MakeLabel(marker)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal alpha = 0.5 - 0.5 * math.cos(os.clock())\n\tmarker.Position = A:Lerp(B, alpha)\n\tlabel.Text = string.format(\"A:Lerp(B, %.2f)\", alpha)\nend)"},
"vec-moveto":{"k":"S","what":"A platform visits waypoints at a fixed speed. The step is capped at the remaining distance, so it stops exactly on each point.","services":[],"variables":"local _speed = 10","functions":"local function MoveTowards(current, goal, maxStep)\n\tlocal offset = goal - current\n\tif offset.Magnitude <= maxStep then return goal end\n\treturn current + offset.Unit * maxStep\nend","setup":"local points = { Vector3.new(-12, 2, 0), Vector3.new(0, 6, -8), Vector3.new(12, 2, 0), Vector3.new(0, 2, 8) }\n\nfor _, point in points do\n\tMakePart(Vector3.new(1, 1, 1), ORIGIN + point, Color3.fromRGB(194, 65, 142), { CanCollide = false })\nend\n\nlocal platform = MakePart(Vector3.new(4, 1, 4), ORIGIN + points[1], Color3.fromRGB(226, 133, 26))\nlocal index = 2","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal goal = ORIGIN + points[index]\n\tplatform.Position = MoveTowards(platform.Position, goal, _speed * deltaTime)\n\tif platform.Position == goal then -- exact, because moveTowards snaps\n\t\tindex = index % #points + 1\n\tend\nend)"},
"vec-bounds":{"k":"S","what":"Six parts drift around. A see-through box built from Min and Max always wraps all of them.","services":[],"variables":"","functions":"","setup":"local random = Random.new()\nlocal parts, homes = {}, {}\n\nfor i = 1, 6 do\n\thomes[i] = ORIGIN\n\t\t+ Vector3.new(random:NextNumber(-10, 10), random:NextNumber(2, 8), random:NextNumber(-8, 8))\n\tparts[i] = MakePart(Vector3.new(1.2, 1.2, 1.2), homes[i], Color3.fromHSV(i / 6, 0.6, 1))\nend\n\nlocal box =\n\tMakePart(Vector3.one, ORIGIN, Color3.fromRGB(226, 133, 26), { Transparency = 0.8, CanCollide = false })\n\nlocal label = MakeLabel(box)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal minCorner, maxCorner =\n\t\tVector3.new(math.huge, math.huge, math.huge), Vector3.new(-math.huge, -math.huge, -math.huge)\n\tfor i, part in parts do\n\t\tpart.Position = homes[i]\n\t\t\t+ Vector3.new(math.sin(now + i) * 3, math.cos(now * 1.3 + i) * 2, math.sin(now * 0.7 + i * 2) * 3)\n\t\tminCorner = minCorner:Min(part.Position)\n\t\tmaxCorner = maxCorner:Max(part.Position)\n\tend\n\tbox.Size = maxCorner - minCorner + Vector3.new(1.2, 1.2, 1.2)\n\tbox.Position = (minCorner + maxCorner) / 2\n\tlabel.Text = string.format(\"size %.1f x %.1f x %.1f\", box.Size.X, box.Size.Y, box.Size.Z)\nend)"},
"vec-avg":{"k":"S","what":"A marker floats at the average position of every player plus three dummies: the centre of the group.","services":[],"variables":"","functions":"","setup":"local dummies = {}\n\nfor i = 1, 3 do\n\tdummies[i] = MakePart(Vector3.new(2, 4, 2), ORIGIN + Vector3.new(0, 2, 0), Color3.fromRGB(18, 147, 154))\nend\n\nlocal centre = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n)\n\nlocal label = MakeLabel(centre, \"centre\")","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal sum, count = Vector3.zero, 0\n\tfor i, dummy in dummies do\n\t\tlocal angle = now * 0.4 + i * 2.1\n\t\tdummy.Position = ORIGIN + Vector3.new(math.cos(angle) * 12, 2, math.sin(angle * 1.3) * 10)\n\t\tsum += dummy.Position\n\t\tcount += 1\n\tend\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tsum += root.Position\n\t\t\tcount += 1\n\t\tend\n\tend\n\tcentre.Position = sum / count + Vector3.new(0, 4, 0)\n\tlabel.Text = \"centre of \" .. count\nend)"},
"vec-physics":{"k":"S","what":"Balls are launched with your own gravity maths (velocity += g·dt, position += velocity·dt). A red marker shows where the formula predicts each one lands.","services":[],"variables":"","functions":"","setup":"local gravity = Vector3.new(0, -workspace.Gravity, 0)\nlocal start = ORIGIN + Vector3.new(-20, 1, 0)\nMakePart(Vector3.new(2, 2, 2), start, Color3.fromRGB(60, 60, 70))\nlocal random = Random.new()","runtime":"while true do\n\tlocal angle, speed = math.rad(random:NextNumber(30, 65)), random:NextNumber(55, 75)\n\tlocal launchVelocity = Vector3.new(math.cos(angle) * speed, math.sin(angle) * speed, 0)\n\tlocal flightTime = 2 * launchVelocity.Y / workspace.Gravity\n\tlocal landing = start + Vector3.new(launchVelocity.X * flightTime, 0, 0)\n\tlocal marker = MakePart(\n\t\tVector3.new(0.3, 4, 4),\n\t\tlanding,\n\t\tColor3.fromRGB(230, 60, 60),\n\t\t{ Shape = Enum.PartType.Cylinder, Orientation = Vector3.new(0, 0, 90), CanCollide = false }\n\t)\n\tlocal ball = MakePart(\n\t\tVector3.new(1, 1, 1),\n\t\tstart,\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\n\tlocal velocity, position, elapsed = launchVelocity, start, 0\n\twhile elapsed < flightTime do\n\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\telapsed += deltaTime\n\t\tvelocity += gravity * deltaTime\n\t\tposition += velocity * deltaTime\n\t\tball.Position = position\n\tend\n\ttask.wait(0.5)\n\tball:Destroy()\n\tmarker:Destroy()\nend"},
"vec-sphere":{"k":"S","what":"150 small balls placed evenly on a sphere with the Fibonacci (golden angle) method.","services":[],"variables":"local _count = 150\nlocal _radius = 10\nlocal _goldenAngle = math.pi * (3 - math.sqrt(5))","functions":"","setup":"local CENTER = ORIGIN + Vector3.new(0, 12, 0)\n\nfor i = 0, _count - 1 do\n\tlocal y = 1 - 2 * (i + 0.5) / _count\n\tlocal ringRadius = math.sqrt(1 - y * y)\n\tlocal angle = i * _goldenAngle\n\tlocal direction = Vector3.new(math.cos(angle) * ringRadius, y, math.sin(angle) * ringRadius)\n\tMakePart(\n\t\tVector3.new(0.6, 0.6, 0.6),\n\t\tCENTER + direction * _radius,\n\t\tColor3.fromHSV(i / _count, 0.6, 1),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n\t)\nend","runtime":""},
"vec-dot":{"k":"S","what":"A guard facing −Z shows the dot product between its LookVector and the direction to you, and turns red when you are inside its 90° cone.","services":[],"variables":"","functions":"","setup":"local guard = MakePart(Vector3.new(3, 5, 2), ORIGIN + Vector3.new(0, 2.5, 0), Color3.fromRGB(90, 160, 230))\n\nMakePart(\n\tVector3.new(2.4, 0.6, 0.3),\n\tguard.Position + Vector3.new(0, 1.5, -1.1),\n\tColor3.new(1, 1, 1),\n\t{ Material = Enum.Material.Neon }\n) -- face\n\nlocal label = MakeLabel(guard)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(guard.Position)\n\tif not root then return end\n\tlocal toTarget = (root.Position - guard.Position).Unit\n\tlocal dot = guard.CFrame.LookVector:Dot(toTarget)\n\tlocal inView = dot > math.cos(math.rad(45))\n\tguard.Color = inView and Color3.fromRGB(230, 60, 60) or Color3.fromRGB(90, 160, 230)\n\tlabel.Text = string.format(\"dot = %.2f  %s\", dot, inView and \"SEES YOU\" or \"\")\nend)"},
"vec-cross":{"k":"S","what":"A block tells you whether you are on its left or its right, from the sign of LookVector:Cross(toTarget).Y.","services":[],"variables":"","functions":"","setup":"local block = MakePart(Vector3.new(3, 3, 4), ORIGIN + Vector3.new(0, 1.5, 0), Color3.fromRGB(163, 162, 165))\n\nMakePart(\n\tVector3.new(2.6, 0.5, 0.3),\n\tblock.Position + Vector3.new(0, 0.8, -2.1),\n\tColor3.new(1, 1, 1),\n\t{ Material = Enum.Material.Neon }\n)\n\nlocal label = MakeLabel(block)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(block.Position)\n\tif not root then return end\n\tlocal toTarget = (root.Position - block.Position).Unit\n\tlocal side = block.CFrame.LookVector:Cross(toTarget).Y\n\tlabel.Text = side > 0.05 and \"you are on my LEFT\"\n\t\tor side < -0.05 and \"you are on my RIGHT\"\n\t\tor \"straight ahead / behind\"\n\tblock.Color = side > 0 and Color3.fromRGB(18, 147, 154) or Color3.fromRGB(194, 65, 142)\nend)"},
"vec-project":{"k":"S","what":"A ball bounces around a box of walls but slides along them instead of stopping: the part of its velocity going into the wall is removed (projection).","services":[],"variables":"local _size = 16","functions":"","setup":"for _, wall in\n\t{\n\t\t{ Vector3.new(_size * 2, 4, 1), Vector3.new(0, 2, -_size) },\n\t\t{ Vector3.new(_size * 2, 4, 1), Vector3.new(0, 2, _size) },\n\t\t{ Vector3.new(1, 4, _size * 2), Vector3.new(-_size, 2, 0) },\n\t\t{ Vector3.new(1, 4, _size * 2), Vector3.new(_size, 2, 0) },\n\t}\n\ndo\n\tMakePart(wall[1], ORIGIN + wall[2], Color3.fromRGB(90, 90, 100))\nend\n\nlocal ball = MakePart(\n\tVector3.new(2, 2, 2),\n\tORIGIN + Vector3.new(0, 1.5, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { ball }\nlocal steer = 0","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tsteer += deltaTime * 0.5\n\tlocal move = Vector3.new(math.cos(steer), 0, math.sin(steer * 0.7)).Unit * 12 * deltaTime -- wanted move\n\tlocal result = workspace:Raycast(ball.Position, move.Unit * (1.1 + move.Magnitude), raycastParams)\n\tif result then\n\t\tlocal normal = result.Normal\n\t\tmove = move - normal * math.min(0, move:Dot(normal)) -- remove only the part going INTO the wall\n\tend\n\tball.Position += move\nend)"},
"vec-angle":{"k":"S","what":"A turret turns toward you at most 90° per second, using the signed angle look:Angle(toTarget, Vector3.yAxis).","services":[],"variables":"local _maxTurn = math.rad(90)","functions":"","setup":"local turret = MakePart(Vector3.new(3, 2, 5), ORIGIN + Vector3.new(0, 1, 0), Color3.fromRGB(226, 133, 26))\nlocal barrel = MakePart(Vector3.new(0.6, 0.6, 3), turret.Position, Color3.fromRGB(60, 60, 70))\nlocal label = MakeLabel(turret)","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tbarrel.CFrame = turret.CFrame * CFrame.new(0, 0.6, -3.5)\n\tlocal root = GetNearestRoot(turret.Position)\n\tif not root then return end\n\tlocal look = turret.CFrame.LookVector\n\tlocal toTarget = (root.Position - turret.Position) * Vector3.new(1, 0, 1)\n\tif toTarget.Magnitude < 0.01 then return end\n\tlocal angle = look:Angle(toTarget, Vector3.yAxis) -- signed: + is to the left\n\tlocal step = math.clamp(angle, -_maxTurn * deltaTime, _maxTurn * deltaTime)\n\tturret.CFrame = turret.CFrame * CFrame.Angles(0, step, 0)\n\tlabel.Text = string.format(\"%.0f degrees to go\", math.deg(angle))\nend)"},
"vec-rotate":{"k":"S","what":"A spread of 8 beams fans out around a slowly turning aim direction, each made by rotating the aim with CFrame.fromAxisAngle.","services":[],"variables":"","functions":"","setup":"local origin = ORIGIN + Vector3.new(0, 4, 0)\nMakePart(Vector3.new(1.5, 1.5, 1.5), origin, Color3.fromRGB(60, 60, 70))\nlocal beams = {}\n\nfor i = 1, 8 do\n\tbeams[i] = MakeLinePart(Color3.fromHSV(i / 8, 0.7, 1))\nend","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal aim = Vector3.new(math.sin(now * 0.5), 0.15, -math.cos(now * 0.5)).Unit\n\tlocal side = aim:Cross(Vector3.yAxis).Unit\n\tlocal tilted = CFrame.fromAxisAngle(side, math.rad(8)):VectorToWorldSpace(aim) -- 8 degrees off the aim\n\tfor i, beam in beams do\n\t\tlocal around = CFrame.fromAxisAngle(aim, (i - 1) / 8 * math.pi * 2) -- spin around the aim\n\t\tlocal direction = around:VectorToWorldSpace(tilted)\n\t\tDrawLine(beam, origin, origin + direction * 25)\n\tend\nend)"},
"vec-closest":{"k":"S","what":"A laser runs between two emitters. Anyone within 2 studs of the line (closest point on a segment) is \"zapped\": the beam turns red.","services":[],"variables":"","functions":"","setup":"local A, B = ORIGIN + Vector3.new(-14, 3, -4), ORIGIN + Vector3.new(14, 3, 4)\nMakePart(Vector3.new(1.5, 6, 1.5), A - Vector3.new(0, 0, 0), Color3.fromRGB(60, 60, 70))\nMakePart(Vector3.new(1.5, 6, 1.5), B, Color3.fromRGB(60, 60, 70))\nlocal beam = MakeLinePart(Color3.fromRGB(60, 220, 100))\nDrawLine(beam, A, B)\n\nlocal marker = MakePart(\n\tVector3.new(0.8, 0.8, 0.8),\n\tA,\n\tColor3.new(1, 1, 1),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal label = MakeLabel(marker)\nlocal direction, length = (B - A).Unit, (B - A).Magnitude","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(A)\n\tif not root then return end\n\tlocal along = math.clamp((root.Position - A):Dot(direction), 0, length)\n\tlocal closest = A + direction * along\n\tlocal distance = (root.Position - closest).Magnitude\n\tmarker.Position = closest\n\tlocal zapped = distance < 2\n\tbeam.Color = zapped and Color3.fromRGB(255, 40, 40) or Color3.fromRGB(60, 220, 100)\n\tlabel.Text = string.format(\"%.1f studs from the laser%s\", distance, zapped and \"  ZAP\" or \"\")\nend)"},
"vec-plane":{"k":"S","what":"A finish gate. Each time a player crosses it front-to-back the sign of (pos − gate):Dot(normal) flips and a lap is counted.","services":[],"variables":"","functions":"","setup":"local gate = MakePart(\n\tVector3.new(14, 10, 0.4),\n\tORIGIN + Vector3.new(0, 5, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ Transparency = 0.6, CanCollide = false }\n)\n\nlocal label = MakeLabel(gate, \"run through me\")\nlocal lastSide, laps = {}, {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tlocal localPosition = gate.CFrame:PointToObjectSpace(root.Position)\n\t\t\tlocal signedDistance = (root.Position - gate.Position):Dot(gate.CFrame.LookVector) -- signed distance\n\t\t\tlocal withinGate = math.abs(localPosition.X) < 7 and math.abs(localPosition.Y) < 5\n\t\t\tif lastSide[player] and lastSide[player] < 0 and signedDistance >= 0 and withinGate then\n\t\t\t\tlaps[player] = (laps[player] or 0) + 1\n\t\t\t\tlabel.Text = player.Name .. \": lap \" .. laps[player]\n\t\t\tend\n\t\t\tlastSide[player] = signedDistance\n\t\tend\n\tend\nend)"},
"vec-basis":{"k":"S","what":"An arrow flies along a curvy path and always points the way it is moving, by building its CFrame from velocity with CFrame.fromMatrix.","services":[],"variables":"","functions":"local function PathAt(now)\n\treturn ORIGIN + Vector3.new(math.sin(now) * 14, 6 + math.sin(now * 2) * 4, math.cos(now * 0.7) * 10)\nend","setup":"local arrow = MakePart(Vector3.new(0.6, 0.6, 4), ORIGIN, Color3.fromRGB(226, 133, 26))\nlocal fin = MakePart(Vector3.new(1.6, 0.2, 1), ORIGIN, Color3.fromRGB(18, 147, 154))","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tlocal position, ahead = PathAt(now), PathAt(now + 0.01)\n\tlocal look = (ahead - position).Unit\n\tlocal right = look:Cross(Vector3.yAxis).Unit\n\tlocal up = right:Cross(look)\n\tlocal frame = CFrame.fromMatrix(position, right, up) -- LookVector = look\n\tarrow.CFrame = frame\n\tfin.CFrame = frame * CFrame.new(0, 0.4, 1.6) -- a fin on top, at the back\nend)"},
"vec-reflect":{"k":"S","what":"A ball bounces around a room using its own maths: raycast ahead, and if it hits, reflect the direction with d − 2(d·n)n.","services":[],"variables":"local _size = 14\nlocal _speed = 18","functions":"","setup":"for _, wall in\n\t{\n\t\t{ Vector3.new(_size * 2, 6, 1), Vector3.new(0, 3, -_size) },\n\t\t{ Vector3.new(_size * 2, 6, 1), Vector3.new(0, 3, _size) },\n\t\t{ Vector3.new(1, 6, _size * 2), Vector3.new(-_size, 3, 0) },\n\t\t{ Vector3.new(1, 6, _size * 2), Vector3.new(_size, 3, 0) },\n\t}\n\ndo\n\tMakePart(wall[1], ORIGIN + wall[2], Color3.fromRGB(90, 90, 100))\nend\n\nMakePart(\n\tVector3.new(4, 6, 4),\n\tORIGIN + Vector3.new(3, 3, -2),\n\tColor3.fromRGB(150, 80, 160),\n\t{ Orientation = Vector3.new(0, 35, 0) }\n)\n\nlocal ball = MakePart(\n\tVector3.new(1.5, 1.5, 1.5),\n\tORIGIN + Vector3.new(-6, 2, 4),\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n)\n\nlocal raycastParams = RaycastParams.new()\nraycastParams.FilterDescendantsInstances = { ball }\nlocal direction = Vector3.new(1, 0, 0.6).Unit","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal step = _speed * deltaTime\n\tlocal result = workspace:Raycast(ball.Position, direction * (step + 0.75), raycastParams)\n\tif result then\n\t\tlocal normal = result.Normal\n\t\tdirection = direction - 2 * direction:Dot(normal) * normal -- bounce\n\tend\n\tball.Position += direction * step\nend)"},
"vec-lead":{"k":"S","what":"A turret leads moving players: it solves the intercept time from your velocity and fires where you will be.","services":[],"variables":"local _bulletSpeed = 60","functions":"local function InterceptTime(shooter, targetPosition, targetVelocity, speed)\n\tlocal offset = targetPosition - shooter\n\tlocal quadA = targetVelocity:Dot(targetVelocity) - speed * speed\n\tlocal quadB = 2 * offset:Dot(targetVelocity)\n\tlocal quadC = offset:Dot(offset)\n\tif math.abs(quadA) < 1e-6 then return quadC > 0 and -quadC / quadB or nil end\n\tlocal discriminant = quadB * quadB - 4 * quadA * quadC\n\tif discriminant < 0 then return nil end\n\tlocal squareRoot = math.sqrt(discriminant)\n\tlocal firstTime, secondTime = (-quadB - squareRoot) / (2 * quadA), (-quadB + squareRoot) / (2 * quadA)\n\tlocal hitTime = math.min(firstTime, secondTime) > 0 and math.min(firstTime, secondTime)\n\t\tor math.max(firstTime, secondTime)\n\treturn hitTime > 0 and hitTime or nil\nend","setup":"local gun = MakePart(Vector3.new(2, 2, 2), ORIGIN + Vector3.new(0, 3, 0), Color3.fromRGB(60, 60, 70))","runtime":"while true do\n\tlocal root = GetNearestRoot(gun.Position, 100)\n\tif root then\n\t\tlocal hitTime = InterceptTime(gun.Position, root.Position, root.AssemblyLinearVelocity, _bulletSpeed)\n\t\tif hitTime then\n\t\t\tlocal aim = root.Position + root.AssemblyLinearVelocity * hitTime\n\t\t\tlocal velocity = (aim - gun.Position).Unit * _bulletSpeed\n\t\t\tlocal bullet = MakePart(\n\t\t\t\tVector3.new(0.6, 0.6, 0.6),\n\t\t\t\tgun.Position,\n\t\t\t\tColor3.fromRGB(226, 133, 26),\n\t\t\t\t{ Shape = Enum.PartType.Ball, CanCollide = false, Material = Enum.Material.Neon }\n\t\t\t)\n\t\t\ttask.spawn(function()\n\t\t\t\tlocal elapsed = 0\n\t\t\t\twhile elapsed < hitTime + 0.3 do\n\t\t\t\t\tlocal deltaTime = runService.Heartbeat:Wait()\n\t\t\t\t\telapsed += deltaTime\n\t\t\t\t\tbullet.Position += velocity * deltaTime\n\t\t\t\tend\n\t\t\t\tbullet:Destroy()\n\t\t\tend)\n\t\tend\n\tend\n\ttask.wait(0.8)\nend"},
"vec-steer":{"k":"S","what":"A seeker chases the nearest player with steering: desired velocity minus current velocity, limited to a maximum force, so it curves and slows near you.","services":[],"variables":"local _maxSpeed = 20\nlocal _maxForce = 25\nlocal _slowRadius = 8","functions":"","setup":"local seeker = MakePart(\n\tVector3.new(1.5, 1.5, 3),\n\tORIGIN + Vector3.new(0, 2, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ CanCollide = false }\n)\n\nlocal velocity = Vector3.zero","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tlocal root = GetNearestRoot(seeker.Position)\n\tif not root then return end\n\tlocal offset = (root.Position - seeker.Position) * Vector3.new(1, 0, 1)\n\tlocal distance = offset.Magnitude\n\tif distance < 0.1 then return end\n\tlocal speed = distance < _slowRadius and _maxSpeed * distance / _slowRadius or _maxSpeed -- arrive\n\tlocal desired = offset / distance * speed\n\tlocal steer = desired - velocity\n\tif steer.Magnitude > _maxForce then steer = steer.Unit * _maxForce end\n\tvelocity += steer * deltaTime\n\tlocal nextPosition = seeker.Position + velocity * deltaTime\n\tif velocity.Magnitude > 0.1 then seeker.CFrame = CFrame.lookAt(nextPosition, nextPosition + velocity) end\nend)"},
"vec-swing":{"k":"S","what":"A ramp tilts back and forth; a block on it is stood up along the surface normal using the shortest rotation between two vectors.","services":[],"variables":"","functions":"local function RotationBetween(fromVector, toVector)\n\tlocal axis = fromVector:Cross(toVector)\n\tlocal angle = math.acos(math.clamp(fromVector:Dot(toVector), -1, 1))\n\tif axis.Magnitude < 1e-6 then return CFrame.identity end\n\treturn CFrame.fromAxisAngle(axis.Unit, angle)\nend","setup":"local ramp = MakePart(Vector3.new(14, 1, 14), ORIGIN + Vector3.new(0, 4, 0), Color3.fromRGB(90, 90, 100))\nlocal block = MakePart(Vector3.new(2, 3, 2), ORIGIN, Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tramp.CFrame = CFrame.new(ramp.Position) * CFrame.Angles(math.sin(now) * 0.5, 0, math.cos(now * 0.7) * 0.5)\n\tlocal normal = ramp.CFrame.UpVector\n\tlocal turn = RotationBetween(Vector3.yAxis, normal) -- world up → surface normal\n\tblock.CFrame = CFrame.new(ramp.Position + normal * 2) * turn\nend)"},
"cf-intro":{"k":"S","what":"A part turns and tilts; the label shows its Position and LookVector, read straight from its CFrame.","services":[],"variables":"","functions":"","setup":"local part = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(0, 4, 0), Color3.fromRGB(226, 133, 26))\nlocal face = MakePart(Vector3.new(1.6, 0.6, 0.2), ORIGIN, Color3.fromRGB(47, 111, 214))\nlocal label = MakeLabel(part)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tpart.CFrame = CFrame.new(ORIGIN + Vector3.new(0, 4, 0))\n\t\t* CFrame.Angles(0, now * 0.6, 0)\n\t\t* CFrame.Angles(math.sin(now) * 0.4, 0, 0)\n\tface.CFrame = part.CFrame * CFrame.new(0, 0, -2.1) -- the front face (-Z)\n\tlocal look = part.CFrame.LookVector\n\tlabel.Text = string.format(\"LookVector (%.2f, %.2f, %.2f)\", look.X, look.Y, look.Z)\nend)"},
"cf-angles":{"k":"S","what":"Three coins spin around Y, X and Z at 90° per second with CFrame.Angles(math.rad(90) * dt ...).","services":[],"variables":"","functions":"","setup":"local coins = {}\n\nfor i, axis in { \"Y\", \"X\", \"Z\" } do\n\tlocal coin = MakePart(\n\t\tVector3.new(0.4, 3, 3),\n\t\tORIGIN + Vector3.new((i - 2) * 6, 4, 0),\n\t\tColor3.fromRGB(250, 200, 40),\n\t\t{ Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon }\n\t)\n\tMakeLabel(coin, \"around \" .. axis)\n\tcoins[axis] = coin\nend\n\nlocal rate = math.rad(90) -- radians per second","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tcoins.Y.CFrame *= CFrame.Angles(0, rate * deltaTime, 0)\n\tcoins.X.CFrame *= CFrame.Angles(rate * deltaTime, 0, 0)\n\tcoins.Z.CFrame *= CFrame.Angles(0, 0, rate * deltaTime)\nend)"},
"cf-lookat":{"k":"S","what":"Two turrets track the nearest player: one aims fully with CFrame.lookAt, the other only turns left/right (target height flattened).","services":[],"variables":"","functions":"","setup":"local full = MakePart(Vector3.new(2, 2, 4), ORIGIN + Vector3.new(-5, 3, 0), Color3.fromRGB(226, 133, 26))\nlocal flat = MakePart(Vector3.new(2, 2, 4), ORIGIN + Vector3.new(5, 3, 0), Color3.fromRGB(18, 147, 154))\nMakeLabel(full, \"full aim\")\nMakeLabel(flat, \"turn only\")","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tlocal target = root.Position\n\tfull.CFrame = CFrame.lookAt(full.Position, target)\n\tflat.CFrame = CFrame.lookAt(flat.Position, Vector3.new(target.X, flat.Position.Y, target.Z))\nend)"},
"cf-offset":{"k":"S","what":"Every player gets a glowing shield floating 5 studs in front of them: root.CFrame * CFrame.new(0, 0, -5).","services":[],"variables":"","functions":"","setup":"local shields = {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tlocal shield = shields[player]\n\t\tif root then\n\t\t\tif not shield then\n\t\t\t\tshield = MakePart(\n\t\t\t\t\tVector3.new(5, 5, 0.4),\n\t\t\t\t\troot.Position,\n\t\t\t\t\tColor3.fromRGB(90, 160, 255),\n\t\t\t\t\t{ Material = Enum.Material.ForceField, CanCollide = false, CanQuery = false }\n\t\t\t\t)\n\t\t\t\tshields[player] = shield\n\t\t\tend\n\t\t\tshield.CFrame = root.CFrame * CFrame.new(0, 0, -5) -- in front, wherever they face\n\t\tend\n\tend\nend)\n\nplayers.PlayerRemoving:Connect(function(player)\n\tif shields[player] then\n\t\tshields[player]:Destroy()\n\t\tshields[player] = nil\n\tend\nend)"},
"cf-order":{"k":"S","what":"Two moons with the same pieces in a different order: Angles then offset = orbit; offset then Angles = spin in place.","services":[],"variables":"","functions":"","setup":"local left = MakePart(Vector3.new(1, 1, 1), ORIGIN + Vector3.new(-8, 4, 0), Color3.fromRGB(18, 147, 154))\nlocal right = MakePart(Vector3.new(1, 1, 1), ORIGIN + Vector3.new(8, 4, 0), Color3.fromRGB(194, 65, 142))\nlocal moonA = MakePart(Vector3.new(1.4, 1.4, 2.4), left.Position, Color3.fromRGB(226, 133, 26))\nlocal moonB = MakePart(Vector3.new(1.4, 1.4, 2.4), right.Position, Color3.fromRGB(226, 133, 26))\nMakeLabel(left, \"Angles, then offset: orbit\")\nMakeLabel(right, \"offset, then Angles: spin\")","runtime":"runService.Heartbeat:Connect(function()\n\tlocal angle = os.clock()\n\tmoonA.CFrame = left.CFrame * CFrame.Angles(0, angle, 0) * CFrame.new(5, 0, 0)\n\tmoonB.CFrame = right.CFrame * CFrame.new(5, 0, 0) * CFrame.Angles(0, angle, 0)\nend)"},
"cf-objectspace":{"k":"S","what":"A turning NPC block reports where you are from its point of view (left/right, front/behind) using PointToObjectSpace.","services":[],"variables":"","functions":"","setup":"local npc = MakePart(Vector3.new(2, 4, 2), ORIGIN + Vector3.new(0, 2, 0), Color3.fromRGB(163, 162, 165))\nlocal face = MakePart(Vector3.new(1.6, 0.6, 0.2), ORIGIN, Color3.fromRGB(47, 111, 214))\nlocal label = MakeLabel(npc)","runtime":"runService.Heartbeat:Connect(function()\n\tnpc.CFrame = CFrame.new(npc.Position) * CFrame.Angles(0, os.clock() * 0.3, 0)\n\tface.CFrame = npc.CFrame * CFrame.new(0, 1, -1.1)\n\tlocal root = GetNearestRoot(npc.Position)\n\tif not root then return end\n\tlocal localPosition = npc.CFrame:PointToObjectSpace(root.Position)\n\tlocal side = localPosition.X > 0 and string.format(\"%.0f right\", localPosition.X)\n\t\tor string.format(\"%.0f left\", -localPosition.X)\n\tlocal depth = localPosition.Z < 0 and string.format(\"%.0f in front\", -localPosition.Z)\n\t\tor string.format(\"%.0f behind\", localPosition.Z)\n\tlabel.Text = side .. \", \" .. depth\nend)"},
"cf-lerp":{"k":"S","what":"A block blends between two very different CFrames (position and rotation) with CFrame:Lerp.","services":[],"variables":"","functions":"","setup":"local A = CFrame.new(ORIGIN + Vector3.new(-10, 2, 0))\nlocal B = CFrame.new(ORIGIN + Vector3.new(10, 8, -6)) * CFrame.fromEulerAnglesYXZ(0.6, 2.4, 0.4)\n\nMakePart(\n\tVector3.new(2, 1, 4),\n\tA.Position,\n\tColor3.fromRGB(18, 147, 154),\n\t{ CFrame = A, Transparency = 0.6, CanCollide = false }\n)\n\nMakePart(\n\tVector3.new(2, 1, 4),\n\tB.Position,\n\tColor3.fromRGB(194, 65, 142),\n\t{ CFrame = B, Transparency = 0.6, CanCollide = false }\n)\n\nlocal block = MakePart(Vector3.new(2, 1, 4), A.Position, Color3.fromRGB(226, 133, 26), { CanCollide = false })","runtime":"runService.Heartbeat:Connect(function()\n\tlocal alpha = 0.5 - 0.5 * math.cos(os.clock() * 0.8)\n\tblock.CFrame = A:Lerp(B, alpha)\nend)"},
"cf-pivot":{"k":"S","what":"A door swings around its hinge edge: hinge * rotation * hinge:Inverse() * closed.","services":[],"variables":"","functions":"","setup":"local hinge = CFrame.new(ORIGIN + Vector3.new(0, 4.5, 0))\nlocal closed = hinge * CFrame.new(3, 0, 0)\nMakePart(Vector3.new(0.6, 9, 0.6), hinge.Position, Color3.fromRGB(60, 60, 70))\nlocal door = MakePart(Vector3.new(6, 9, 0.5), closed.Position, Color3.fromRGB(150, 110, 70))","runtime":"runService.Heartbeat:Connect(function()\n\tlocal openAngle = math.rad(100) * (0.5 - 0.5 * math.cos(os.clock()))\n\tdoor.CFrame = hinge * CFrame.Angles(0, openAngle, 0) * hinge:Inverse() * closed\nend)"},
"cf-camera":{"k":"L","what":"An over-the-shoulder camera: hold right mouse to look around. Built from focus * yaw * pitch * offset, pulled in front of walls with a raycast.","services":["UserInputService"],"variables":"local _shoulderOffset = 2\nlocal _distance = 10","functions":"","setup":"local yaw, pitch = 0, math.rad(-10)\nMakePart(Vector3.new(20, 12, 1), ORIGIN + Vector3.new(0, 6, 10), Color3.fromRGB(90, 90, 100)) -- a wall to test with","runtime":"userInputService.InputChanged:Connect(function(input)\n\tif\n\t\tinput.UserInputType == Enum.UserInputType.MouseMovement\n\t\tand userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)\n\tthen\n\t\tyaw -= input.Delta.X * 0.005\n\t\tpitch = math.clamp(pitch - input.Delta.Y * 0.005, math.rad(-70), math.rad(40))\n\tend\nend)\n\nlocal raycastParams = RaycastParams.new()\n\nrunService:BindToRenderStep(\"ShoulderCam\", Enum.RenderPriority.Camera.Value + 1, function()\n\tlocal root = GetMyRootPart()\n\tif not root then return end\n\tcamera.CameraType = Enum.CameraType.Scriptable\n\tuserInputService.MouseBehavior = userInputService:IsMouseButtonPressed(Enum.UserInputType.MouseButton2)\n\t\t\tand Enum.MouseBehavior.LockCurrentPosition\n\t\tor Enum.MouseBehavior.Default\n\tlocal focus = CFrame.new(root.Position + Vector3.new(0, 2, 0))\n\t\t* CFrame.Angles(0, yaw, 0)\n\t\t* CFrame.Angles(pitch, 0, 0)\n\tlocal wanted = focus * CFrame.new(_shoulderOffset, 0, _distance)\n\traycastParams.FilterDescendantsInstances = { player.Character }\n\tlocal hit = workspace:Raycast(focus.Position, wanted.Position - focus.Position, raycastParams)\n\tlocal position = hit and hit.Position + hit.Normal * 0.3 or wanted.Position\n\tcamera.CFrame = CFrame.new(position) * wanted.Rotation\nend)"},
"cf-weld":{"k":"S","what":"Every player gets a shield welded to their back. Weld.C0 says where on the torso, C1 which point of the shield sits there.","services":[],"variables":"","functions":"local function GiveShield(character)\n\tlocal root = character:WaitForChild(\"HumanoidRootPart\")\n\tlocal shield = Instance.new(\"Part\")\n\tshield.Size = Vector3.new(3, 3.5, 0.4)\n\tshield.Color = Color3.fromRGB(150, 110, 70)\n\tshield.CanCollide = false\n\tshield.Massless = true\n\tshield.Parent = character\n\tlocal weld = Instance.new(\"Weld\")\n\tweld.Part0 = root\n\tweld.Part1 = shield\n\tweld.C0 = CFrame.new(0, 0.3, 0.8) -- on the back (+Z is behind)\n\tweld.C1 = CFrame.Angles(0, 0, math.rad(15)) -- tilted a little\n\tweld.Parent = shield\nend","setup":"","runtime":"players.PlayerAdded:Connect(function(player)\n\tplayer.CharacterAdded:Connect(GiveShield)\nend)\n\nfor _, player in players:GetPlayers() do\n\tplayer.CharacterAdded:Connect(GiveShield)\n\tif player.Character then GiveShield(player.Character) end\nend"},
"cf-localvel":{"k":"S","what":"A label over each player shows their forward and sideways speed, from root.CFrame:VectorToObjectSpace(velocity).","services":[],"variables":"","functions":"","setup":"local labels = {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tif not labels[player] or not labels[player].Parent or labels[player].Parent.Parent ~= root then\n\t\t\t\tlabels[player] = MakeLabel(root)\n\t\t\tend\n\t\t\tlocal localVelocity = root.CFrame:VectorToObjectSpace(root.AssemblyLinearVelocity)\n\t\t\tlabels[player].Text =\n\t\t\t\tstring.format(\"forward %.0f  sideways %.0f\", -localVelocity.Z, localVelocity.X)\n\t\tend\n\tend\nend)"},
"cf-euler":{"k":"S","what":"A compass label over each player shows their heading in degrees, read back with ToEulerAnglesYXZ.","services":[],"variables":"","functions":"","setup":"local labels = {}","runtime":"runService.Heartbeat:Connect(function()\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tif not labels[player] or not labels[player].Parent or labels[player].Parent.Parent ~= root then\n\t\t\t\tlabels[player] = MakeLabel(root)\n\t\t\tend\n\t\t\tlocal _, yaw, _ = root.CFrame:ToEulerAnglesYXZ()\n\t\t\tlocal heading = (math.deg(yaw) + 360) % 360\n\t\t\tlocal names = { \"N\", \"NW\", \"W\", \"SW\", \"S\", \"SE\", \"E\", \"NE\" }\n\t\t\tlabels[player].Text =\n\t\t\t\tstring.format(\"%s  %.0f degrees\", names[math.floor((heading + 22.5) / 45) % 8 + 1], heading)\n\t\tend\n\tend\nend)"},
"cf-slerp":{"k":"S","what":"Two blocks turn between the same two orientations: CFrame:Lerp (smooth, shortest path) vs lerping the three angles (wobbly detour).","services":[],"variables":"","functions":"","setup":"local goalAngles = Vector3.new(math.rad(70), math.rad(150), math.rad(120)) -- pitch, yaw, roll\n\nlocal slerpBlock =\n\tMakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(-6, 5, 0), Color3.fromRGB(226, 133, 26))\n\nlocal angleBlock = MakePart(Vector3.new(2, 1, 4), ORIGIN + Vector3.new(6, 5, 0), Color3.fromRGB(230, 60, 60))\nMakeLabel(slerpBlock, \"CFrame:Lerp\")\nMakeLabel(angleBlock, \"lerping angles\")\nlocal slerpStart, angleStart = CFrame.new(slerpBlock.Position), CFrame.new(angleBlock.Position)\nlocal goalRotation = CFrame.fromEulerAnglesYXZ(goalAngles.X, goalAngles.Y, goalAngles.Z)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal alpha = 0.5 - 0.5 * math.cos(os.clock() * 0.7)\n\tslerpBlock.CFrame = slerpStart:Lerp(slerpStart * goalRotation, alpha)\n\tlocal angles = goalAngles * alpha\n\tangleBlock.CFrame = angleStart * CFrame.fromEulerAnglesYXZ(angles.X, angles.Y, angles.Z)\nend)"},
"m-sincos":{"k":"S","what":"Twelve orbs placed evenly around a circle with cos and sin, slowly rotating, plus one bobbing up and down with math.sin.","services":[],"variables":"local _count = 12\nlocal _radius = 10","functions":"","setup":"local CENTER = ORIGIN + Vector3.new(0, 3, 0)\nlocal orbs = {}\n\nfor i = 1, _count do\n\torbs[i] = MakePart(\n\t\tVector3.new(1.2, 1.2, 1.2),\n\t\tCENTER,\n\t\tColor3.fromHSV(i / _count, 0.6, 1),\n\t\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n\t)\nend\n\nlocal bobber = MakePart(\n\tVector3.new(2, 2, 2),\n\tCENTER,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Shape = Enum.PartType.Ball, Material = Enum.Material.Neon }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal now = os.clock()\n\tfor i, orb in orbs do\n\t\tlocal angle = (i - 1) / _count * math.pi * 2 + now * 0.5\n\t\torb.Position = CENTER + Vector3.new(math.cos(angle) * _radius, 0, math.sin(angle) * _radius)\n\tend\n\tbobber.Position = CENTER + Vector3.new(0, math.sin(now * 2) * 1.5, 0)\nend)"},
"m-atan2":{"k":"S","what":"A tank body turns only around Y toward you, using yaw = math.atan2(-direction.X, -direction.Z).","services":[],"variables":"","functions":"","setup":"local tank = MakePart(Vector3.new(4, 2, 6), ORIGIN + Vector3.new(0, 1, 0), Color3.fromRGB(70, 110, 70))\nlocal barrel = MakePart(Vector3.new(0.6, 0.6, 4), ORIGIN, Color3.fromRGB(40, 60, 40))\nlocal label = MakeLabel(tank)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(tank.Position)\n\tif not root then return end\n\tlocal direction = root.Position - tank.Position\n\tlocal yaw = math.atan2(-direction.X, -direction.Z) -- 0 = facing -Z\n\ttank.CFrame = CFrame.new(tank.Position) * CFrame.Angles(0, yaw, 0)\n\tbarrel.CFrame = tank.CFrame * CFrame.new(0, 0.8, -4.5)\n\tlabel.Text = string.format(\"yaw %.0f degrees\", math.deg(yaw))\nend)"},
"m-clamp":{"k":"S","what":"A drone follows the nearest player but math.clamp keeps it inside a 20 × 20 arena (outlined).","services":[],"variables":"local _limit = 10","functions":"","setup":"for _, edge in\n\t{\n\t\t{ Vector3.new(_limit * 2, 0.4, 0.4), Vector3.new(0, 0.2, -_limit) },\n\t\t{ Vector3.new(_limit * 2, 0.4, 0.4), Vector3.new(0, 0.2, _limit) },\n\t\t{ Vector3.new(0.4, 0.4, _limit * 2), Vector3.new(-_limit, 0.2, 0) },\n\t\t{ Vector3.new(0.4, 0.4, _limit * 2), Vector3.new(_limit, 0.2, 0) },\n\t}\n\ndo\n\tMakePart(\n\t\tedge[1],\n\t\tORIGIN + edge[2],\n\t\tColor3.fromRGB(226, 133, 26),\n\t\t{ Material = Enum.Material.Neon, CanCollide = false }\n\t)\nend\n\nlocal drone = MakePart(\n\tVector3.new(2, 1, 2),\n\tORIGIN + Vector3.new(0, 4, 0),\n\tColor3.fromRGB(18, 147, 154),\n\t{ CanCollide = false }\n)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tlocal offset = root.Position - ORIGIN\n\tlocal clamped =\n\t\tVector3.new(math.clamp(offset.X, -_limit, _limit), 4, math.clamp(offset.Z, -_limit, _limit))\n\tdrone.Position = drone.Position:Lerp(ORIGIN + clamped, 0.15)\nend)"},
"m-snap":{"k":"S","what":"A see-through preview block snaps to a 4-stud grid under the nearest player: math.round(x / 4) * 4.","services":[],"variables":"local _grid = 4","functions":"local function Snap(value)\n\treturn math.round(value / _grid) * _grid\nend","setup":"local preview = MakePart(\n\tVector3.new(_grid, _grid, _grid),\n\tORIGIN,\n\tColor3.fromRGB(226, 133, 26),\n\t{ Transparency = 0.5, CanCollide = false, CanQuery = false }\n)\n\nlocal label = MakeLabel(preview)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(ORIGIN)\n\tif not root then return end\n\tlocal spot = root.Position + root.CFrame.LookVector * 6 -- a spot in front of you\n\tpreview.Position = Vector3.new(Snap(spot.X), _grid / 2, Snap(spot.Z))\n\tlabel.Text = string.format(\"(%d, %d)\", preview.Position.X, preview.Position.Z)\nend)"},
"m-noise":{"k":"S","what":"A 24 × 24 patch of terrain columns whose heights come from math.noise.","services":[],"variables":"local _size = 24\nlocal _scale = 0.12\nlocal _amplitude = 8","functions":"","setup":"for x = 1, _size do\n\tfor z = 1, _size do\n\t\tlocal noise = math.noise(x * _scale, z * _scale, 3) -- about -0.5..0.5\n\t\tlocal height = math.max(0.5, 4 + noise * _amplitude)\n\t\tMakePart(\n\t\t\tVector3.new(2, height, 2),\n\t\t\tORIGIN + Vector3.new((x - _size / 2) * 2, height / 2, (z - _size / 2) * 2),\n\t\t\tColor3.fromRGB(70, 150, 90)\n\t\t\t\t:Lerp(Color3.fromRGB(240, 240, 230), math.clamp((height - 2) / 8, 0, 1))\n\t\t)\n\tend\n\ttask.wait()\nend","runtime":""},
"m-exp":{"k":"S","what":"A pet follows each player smoothly at any frame rate, using alpha = 1 − math.exp(−speed × dt).","services":[],"variables":"local _speed = 5","functions":"","setup":"local pets = {}","runtime":"runService.Heartbeat:Connect(function(deltaTime)\n\tfor _, player in players:GetPlayers() do\n\t\tlocal root = player.Character and player.Character:FindFirstChild(\"HumanoidRootPart\")\n\t\tif root then\n\t\t\tlocal pet = pets[player]\n\t\t\tif not pet then\n\t\t\t\tpet = MakePart(Vector3.new(1.5, 1.5, 1.5), root.Position, Color3.fromRGB(226, 133, 26), {\n\t\t\t\t\tShape = Enum.PartType.Ball,\n\t\t\t\t\tCanCollide = false,\n\t\t\t\t\tCanQuery = false,\n\t\t\t\t\tMaterial = Enum.Material.Neon,\n\t\t\t\t})\n\t\t\t\tpets[player] = pet\n\t\t\tend\n\t\t\tlocal goal = (root.CFrame * CFrame.new(3, 2, 3)).Position\n\t\t\tpet.Position = pet.Position:Lerp(goal, 1 - math.exp(-_speed * deltaTime))\n\t\tend\n\tend\nend)"},
"m-easing":{"k":"S","what":"A row of blocks slides back and forth, each with a different Enum.EasingStyle, so you can compare them side by side.","services":[],"variables":"","functions":"","setup":"local styles = { \"Linear\", \"Quad\", \"Cubic\", \"Sine\", \"Exponential\", \"Back\", \"Elastic\", \"Bounce\" }\n\nfor i, name in styles do\n\tlocal block = MakePart(\n\t\tVector3.new(2, 2, 2),\n\t\tORIGIN + Vector3.new(-12, 1, (i - 4.5) * 3),\n\t\tColor3.fromHSV(i / #styles, 0.6, 1)\n\t)\n\tMakeLabel(block, name)\n\tlocal tweenInfo = TweenInfo.new(2, Enum.EasingStyle[name], Enum.EasingDirection.Out, -1, true, 0.5)\n\ttweenService:Create(block, tweenInfo, { Position = ORIGIN + Vector3.new(12, 1, (i - 4.5) * 3) }):Play()\nend","runtime":""},
"m-mod":{"k":"S","what":"A guard patrols six pads forever: index = index % #pads + 1 wraps back to the first.","services":[],"variables":"","functions":"","setup":"local pads = {}\n\nfor i = 1, 6 do\n\tlocal angle = (i - 1) / 6 * math.pi * 2\n\tpads[i] = MakePart(\n\t\tVector3.new(3, 0.4, 3),\n\t\tORIGIN + Vector3.new(math.cos(angle) * 12, 0.2, math.sin(angle) * 12),\n\t\tColor3.fromRGB(163, 162, 165)\n\t)\n\tMakeLabel(pads[i], tostring(i))\nend\n\nlocal guard =\n\tMakePart(Vector3.new(2, 4, 2), pads[1].Position + Vector3.new(0, 2, 0), Color3.fromRGB(226, 133, 26))\n\nlocal index = 1","runtime":"while true do\n\tpads[index].Color = Color3.fromRGB(163, 162, 165)\n\tindex = index % #pads + 1 -- 1, 2, ... 6, 1, 2 ...\n\tpads[index].Color = Color3.fromRGB(226, 133, 26)\n\tlocal tween = tweenService:Create(\n\t\tguard,\n\t\tTweenInfo.new(1.2, Enum.EasingStyle.Linear),\n\t\t{ Position = pads[index].Position + Vector3.new(0, 2, 0) }\n\t)\n\ttween:Play()\n\ttween.Completed:Wait()\nend"},
"m-map":{"k":"S","what":"A lamp gets brighter the closer you are: brightness = 1 − inverseLerp(near, far, distance), clamped.","services":[],"variables":"local _near = 6\nlocal _far = 30","functions":"local function InverseLerp(low, high, value)\n\treturn (value - low) / (high - low)\nend","setup":"local lamp = MakePart(\n\tVector3.new(2, 2, 2),\n\tORIGIN + Vector3.new(0, 4, 0),\n\tColor3.fromRGB(255, 220, 120),\n\t{ Material = Enum.Material.Neon }\n)\n\nlocal light = Instance.new(\"PointLight\")\nlight.Range = 30\nlight.Parent = lamp\nlocal label = MakeLabel(lamp)","runtime":"runService.Heartbeat:Connect(function()\n\tlocal root = GetNearestRoot(lamp.Position)\n\tif not root then return end\n\tlocal distance = (root.Position - lamp.Position).Magnitude\n\tlocal alpha = math.clamp(InverseLerp(_near, _far, distance), 0, 1)\n\tlight.Brightness = (1 - alpha) * 5\n\tlamp.Transparency = alpha * 0.8\n\tlabel.Text = string.format(\"%.0f studs -> brightness %.2f\", distance, light.Brightness)\nend)"},
"m-angdiff":{"k":"S","what":"A turret turns toward a target that jumps between headings near ±180°. With angle wrapping it always takes the short way round.","services":[],"variables":"","functions":"local function AngleDifference(from, to) -- degrees, always -180..180\n\treturn (to - from + 180) % 360 - 180\nend","setup":"local turret = MakePart(Vector3.new(2, 2, 5), ORIGIN + Vector3.new(0, 1, 0), Color3.fromRGB(226, 133, 26))\nlocal target = MakePart(Vector3.new(1, 1, 1), ORIGIN, Color3.fromRGB(194, 65, 142), { CanCollide = false })\nlocal label = MakeLabel(turret)\nlocal yaw, targetYaw = 0, 170","runtime":"task.spawn(function()\n\twhile true do\n\t\ttargetYaw = targetYaw > 0 and -170 or 170 -- jump across the 180 line\n\t\ttask.wait(3)\n\tend\nend)\n\nrunService.Heartbeat:Connect(function(deltaTime)\n\tlocal difference = AngleDifference(yaw, targetYaw)\n\tyaw += math.clamp(difference, -120 * deltaTime, 120 * deltaTime)\n\tturret.CFrame = CFrame.new(turret.Position) * CFrame.Angles(0, math.rad(yaw), 0)\n\ttarget.Position = turret.Position\n\t\t+ Vector3.new(-math.sin(math.rad(targetYaw)), 0, -math.cos(math.rad(targetYaw))) * 8\n\tlabel.Text = string.format(\"turning %.0f degrees (the short way)\", difference)\nend)"},
"m-spring":{"k":"S","what":"A box springs toward a goal that jumps every 2 seconds: acceleration = −stiffness·offset − damping·velocity, stepped at a fixed rate.","services":[],"variables":"local _stiffness = 120\nlocal _dampingRatio = 0.3\nlocal _damping = 2 * _dampingRatio * math.sqrt(_stiffness)","functions":"","setup":"local box = MakePart(\n\tVector3.new(2, 2, 2),\n\tORIGIN + Vector3.new(0, 4, 0),\n\tColor3.fromRGB(226, 133, 26),\n\t{ CanCollide = false }\n)\n\nlocal goalMarker = MakePart(\n\tVector3.new(0.6, 0.6, 0.6),\n\tORIGIN,\n\tColor3.fromRGB(47, 111, 214),\n\t{ Shape = Enum.PartType.Ball, CanCollide = false }\n)\n\nlocal position, velocity, goal = 0, 0, 0","runtime":"task.spawn(function()\n\twhile true do\n\t\ttask.wait(2)\n\t\tgoal = goal == 0 and 8 or 0\n\tend\nend)\n\nlocal STEP, accumulator = 1 / 240, 0\n\nrunService.Heartbeat:Connect(function(deltaTime)\n\taccumulator += math.min(deltaTime, 0.1)\n\twhile accumulator >= STEP do\n\t\taccumulator -= STEP\n\t\tlocal acceleration = -_stiffness * (position - goal) - _damping * velocity\n\t\tvelocity += acceleration * STEP\n\t\tposition += velocity * STEP\n\tend\n\tbox.Position = ORIGIN + Vector3.new(position - 4, 4, 0)\n\tgoalMarker.Position = ORIGIN + Vector3.new(goal - 4, 6, 0)\nend)"},
"m-growth":{"k":"S","what":"Prints an XP table for levels 1 to 15 with an exponential curve, and works the level back out from total XP with math.log.","services":[],"variables":"local _base = 100\nlocal _growth = 1.15","functions":"local function XpNeeded(level)\n\treturn math.floor(_base * _growth ^ (level - 1))\nend\n\nlocal function TotalXpFor(level)\n\treturn _base * (_growth ^ (level - 1) - 1) / (_growth - 1)\nend -- XP to reach this level\n\nlocal function LevelFromXp(xp)\n\treturn math.floor(math.log(xp * (_growth - 1) / _base + 1) / math.log(_growth)) + 1\nend","setup":"for level = 1, 15 do\n\tprint(\n\t\tstring.format(\n\t\t\t\"level %2d -> %2d needs %5d XP   (total so far %6.0f)\",\n\t\t\tlevel,\n\t\t\tlevel + 1,\n\t\t\tXpNeeded(level),\n\t\t\tTotalXpFor(level)\n\t\t)\n\t)\nend\n\nfor _, xp in { 0, 500, 2500, 12000 } do\n\tprint(xp, \"total XP is level\", LevelFromXp(xp))\nend\n\nfor level = 1, 15 do\n\tlocal height = XpNeeded(level) / 40\n\tlocal bar = MakePart(\n\t\tVector3.new(1.5, height, 1.5),\n\t\tORIGIN + Vector3.new((level - 8) * 2, height / 2, 0),\n\t\tColor3.fromHSV(level / 20, 0.6, 0.9)\n\t)\n\tif level % 5 == 0 then MakeLabel(bar, \"lvl \" .. level .. \": \" .. XpNeeded(level)) end\nend","runtime":""}
});
})();
